#!/usr/bin/env python3
"""Adds what FAT Map needs to the Android project generated by `flutter create`.

- INTERNET permission (Flutter only adds it to debug builds)
- location permissions (GPS dot / "find my location")
- <queries> entry so "Open in Google Maps" works on Android 11+
- app name "FAT Map"

Safe to run more than once.
"""
import pathlib
import re
import sys

manifest = pathlib.Path("android/app/src/main/AndroidManifest.xml")
if not manifest.exists():
    sys.exit("android/ not found - run `flutter create` first (see README)")

s = manifest.read_text(encoding="utf-8")

perms = [
    "android.permission.INTERNET",
    "android.permission.ACCESS_FINE_LOCATION",
    "android.permission.ACCESS_COARSE_LOCATION",
]
add = "".join(
    f'    <uses-permission android:name="{p}"/>\n' for p in perms if f'"{p}"' not in s
)
if add:
    s = re.sub(r"(<manifest\b[^>]*>\s*\n)", lambda m: m.group(1) + add, s, count=1)

view_intent = (
    "        <intent>\n"
    '            <action android:name="android.intent.action.VIEW"/>\n'
    '            <data android:scheme="https"/>\n'
    "        </intent>\n"
)
if "android.intent.action.VIEW" not in s:
    if "<queries>" in s:
        s = s.replace("<queries>\n", "<queries>\n" + view_intent, 1)
    else:
        s = s.replace("</manifest>", "    <queries>\n" + view_intent + "    </queries>\n</manifest>", 1)

s = re.sub(r'android:label="[^"]*"', 'android:label="FAT Map"', s, count=1)

manifest.write_text(s, encoding="utf-8")
print("AndroidManifest.xml patched")
